export function makeCacheKey(resumeUpdatedAt: number, model: string, job: JobPosting): string {
  const basis = `${resumeUpdatedAt}|${model}|${job.url}|${job.rawText.length}|${job.rawText.slice(0, 500)}`
  return 'm_' + djb2(basis)
}

/** 发送给模型前对画像做 PII 脱敏（匹配不需要真实姓名/联系方式） */
export function redactProfile(p: ResumeProfile): ResumeProfile {
  return {
    ...p,
    basics: {
      ...p.basics,
      name: p.basics?.name ? '候选人' : undefined,
      phone: undefined,
      email: undefined,
    },
  }
}

export async function runMatch(
  settings: AppSettings,
  profile: ResumeProfile,
  job: JobPosting,
  signal?: AbortSignal,
): Promise<MatchAnalysis> {
  const today = new Date().toISOString().slice(0, 10)
  const p = settings.redactPII ? redactProfile(profile) : profile
  const { system, user } = buildMatchPrompt(p, job, today)
  const raw = await llmComplete(settings.llm, {
    system,
    user,
    json: true,
    maxTokens: 4096,
    temperature: 0.3,
    signal,
  })
  const parsed = extractJSON<Partial<MatchAnalysis>>(raw)
  return normalizeAnalysis(parsed, job, settings.llm.model)
}

const RECOMMENDATIONS: Recommendation[] = ['强烈推荐', '推荐', '可以一试', '谨慎', '不建议']
const GAP_KINDS: GapKind[] = ['rewriteable', 'realGap', 'structural']
const LEVELS: Level[] = ['高', '中', '低']

function normalizeAnalysis(
  a: Partial<MatchAnalysis>,
  job: JobPosting,
  model: string,
): MatchAnalysis {
  const dimensions: MatchDimension[] = Array.isArray(a.dimensions)
    ? a.dimensions.map((d) => ({
        key: (d?.key ?? 'other') as MatchDimension['key'],
        label: String(d?.label ?? d?.key ?? '维度'),
        score: clamp(num(d?.score), 0, 100),
        weight: clampFloat(num(d?.weight), 0, 1),
        comment: String(d?.comment ?? ''),
      }))
    : []

  let overall = clamp(num(a.overallScore), 0, 100)
  if (!overall && dimensions.length) {
    const wsum = dimensions.reduce((s, d) => s + d.weight, 0) || 1
    overall = clamp(dimensions.reduce((s, d) => s + d.score * d.weight, 0) / wsum, 0, 100)
  }

  const recommendation: Recommendation = RECOMMENDATIONS.includes(a.recommendation as Recommendation)
    ? (a.recommendation as Recommendation)
    : scoreToRecommendation(overall)

  return {
    overallScore: overall,
    recommendation,
    confidence: (['高', '中', '低'] as const).includes(a.confidence as never)
      ? (a.confidence as MatchAnalysis['confidence'])
      : '中',
    summary: String(a.summary ?? ''),
    dimensions,
    strengths: arr(a.strengths),
    gaps: arr(a.gaps).map((g) => ({
      requirement: String(g?.requirement ?? ''),
      kind: GAP_KINDS.includes(g?.kind as GapKind) ? (g.kind as GapKind) : 'realGap',
      severity: LEVELS.includes(g?.severity as Level) ? (g.severity as Level) : '中',
      suggestion: String(g?.suggestion ?? ''),
    })),
    risks: arr(a.risks),
    resumeSuggestions: arr(a.resumeSuggestions),
    skillUpSuggestions: arr(a.skillUpSuggestions).map((x) => String(x)),
    talkingPoints: arr(a.talkingPoints).map((x) => String(x)),
    jdRedFlags: arr(a.jdRedFlags).map((x) => String(x)),
    interview: {
      likelyQuestions: arr(a.interview?.likelyQuestions),
      focusAreas: arr(a.interview?.focusAreas).map((x) => String(x)),
    },
    jobTitle: job.title,
    company: job.company,
    analyzedAt: Date.now(),
    model,
  }
}

function scoreToRecommendation(score: number): Recommendation {
  if (score >= 85) return '强烈推荐'
  if (score >= 75) return '推荐'
  if (score >= 60) return '可以一试'
  if (score >= 45) return '谨慎'
  return '不建议'
}

function num(v: unknown): number {
  const n = typeof v === 'string' ? parseFloat(v) : (v as number)
  return Number.isFinite(n) ? n : 0
}
function clamp(n: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, Math.round(n)))
}
function clampFloat(n: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, n))
}
function arr<T>(v: T[] | undefined): T[] {
  return Array.isArray(v) ? v : []
}
function djb2(str: string): string {
  let h = 5381
  for (let i = 0; i < str.length; i++) h = (h * 33) ^ str.charCodeAt(i)
  return (h >>> 0).toString(36)
}

