type Status = 'idle' | 'loading' | 'done' | 'error'

export function SidePanel() {
  const [resume, setResume] = useState<StoredResume | null>(null)
  const [settings, setSettings] = useState<AppSettings | null>(null)
  const [loaded, setLoaded] = useState(false)
  const [tabId, setTabId] = useState<number | null>(null)
  const [job, setJob] = useState<JobPosting | null>(null)
  const [status, setStatus] = useState<Status>('idle')
  const [analysis, setAnalysis] = useState<MatchAnalysis | null>(null)
  const [cached, setCached] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [manual, setManual] = useState('')
  const abortRef = useRef<AbortController | null>(null)
  const lastJobKeyRef = useRef('')

  const hasResume = !!resume?.profile
  const hasKey = !!settings?.llm.apiKey

  // 按需把自包含抽取函数注入当前标签执行（绕开页面 CSP，无需常驻内容脚本）
  const refreshJob = useCallback(async (tid: number) => {
    try {
      const results = await chrome.scripting.executeScript({ target: { tabId: tid }, func: extractJobInPage })
      const job = (results?.[0]?.result as JobPosting | null) ?? null
      const key = job ? `${job.url}|${job.rawText.length}` : ''
      if (key === lastJobKeyRef.current) return // 无变化，避免重复触发分析
      lastJobKeyRef.current = key
      setJob(job)
    } catch {
      // 非招聘站点 / 无注入权限 / chrome:// 页面
      if (lastJobKeyRef.current !== '') {
        lastJobKeyRef.current = ''
        setJob(null)
      }
    }
  }, [])

  // 初始加载
  useEffect(() => {
    void (async () => {
      setResume(await getResume())
      setSettings(await getSettings())
      setLoaded(true)
      const [tab] = await chrome.tabs.query({ active: true, lastFocusedWindow: true })
      if (tab?.id != null) {
        setTabId(tab.id)
        void refreshJob(tab.id)
      }
    })()
  }, [refreshJob])

  // 简历/设置变更（在设置页修改后）实时同步
  useEffect(() => {
    const onCh = (_c: unknown, area: string) => {
      if (area !== 'local') return
      void getResume().then(setResume)
      void getSettings().then(setSettings)
    }
    chrome.storage.onChanged.addListener(onCh)
    return () => chrome.storage.onChanged.removeListener(onCh)
  }, [])

  // 侧边栏可见时轮询当前标签，捕捉站内切换岗位（SPA 无 URL 变化时）
  useEffect(() => {
    const iv = setInterval(() => {
      if (document.visibilityState === 'visible' && tabId != null) void refreshJob(tabId)
    }, 2500)
    return () => clearInterval(iv)
  }, [tabId, refreshJob])

  // 切换/刷新标签页时更新当前岗位
  useEffect(() => {
    const onAct = (info: { tabId: number }) => {
      setTabId(info.tabId)
      void refreshJob(info.tabId)
    }
    const onUpd = (tid: number, ci: { status?: string }) => {
      if (tid === tabId && ci.status === 'complete') void refreshJob(tid)
    }
    chrome.tabs.onActivated.addListener(onAct)
    chrome.tabs.onUpdated.addListener(onUpd)
    return () => {
      chrome.tabs.onActivated.removeListener(onAct)
      chrome.tabs.onUpdated.removeListener(onUpd)
    }
  }, [tabId, refreshJob])

  const runAnalyze = useCallback(
    async (force: boolean) => {
      if (!resume?.profile || !settings || !job) return
      abortRef.current?.abort()
      const ctrl = new AbortController()
      abortRef.current = ctrl
      setStatus('loading')
      setError(null)
      try {
        const r = await getOrRunAnalysis(settings, resume, job, { force, signal: ctrl.signal })
        if (ctrl.signal.aborted) return
        setAnalysis(r.analysis)
        setCached(r.cached)
        setStatus('done')
      } catch (e) {
        if (ctrl.signal.aborted) return
        setError(e instanceof Error ? e.message : String(e))
        setStatus('error')
      }
    },
    [resume, settings, job],
  )

  // 岗位/简历/模型变化时：缓存优先，命中即显示；否则按 autoAnalyze 决定是否自动分析
  useEffect(() => {
    if (!hasResume || !hasKey || !job || !resume || !settings) {
      setStatus('idle')
      setAnalysis(null)
      return
    }
    let cancelled = false
    void (async () => {
      const key = makeCacheKey(resume.updatedAt, settings.llm.model, job)
      const hit = await getCachedAnalysis(key)
      if (cancelled) return
      if (hit) {
        setAnalysis(hit)
        setCached(true)
        setStatus('done')
      } else if (settings.autoAnalyze) {
        void runAnalyze(false)
      } else {
        setStatus('idle')
        setAnalysis(null)
      }
    })()
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [job?.url, job?.rawText.length, resume?.updatedAt, hasKey, settings?.llm.model, settings?.autoAnalyze])

  const openOptions = () => chrome.runtime.openOptionsPage()

