type ResumeStage = 'idle' | 'parsing' | 'building' | 'error'

export function Options() {
  const [s, setS] = useState<AppSettings>(DEFAULT_SETTINGS)
  const [resume, setResumeState] = useState<StoredResume | null>(null)
  const [loaded, setLoaded] = useState(false)
  const [testing, setTesting] = useState(false)
  const [testMsg, setTestMsg] = useState<{ ok: boolean; text: string } | null>(null)
  const [stage, setStage] = useState<ResumeStage>('idle')
  const [resumeMsg, setResumeMsg] = useState<string>('')
  const fileRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    void (async () => {
      setS(await getSettings())
      setResumeState(await getResume())
      setLoaded(true)
    })()
  }, [])

  function update(patch: Partial<AppSettings>) {
    setS((prev) => {
      const next = { ...prev, ...patch }
      void setSettings(next)
      return next
    })
  }
  function updateLLM(patch: Partial<AppSettings['llm']>) {
    setS((prev) => {
      const next = { ...prev, llm: { ...prev.llm, ...patch } }
      void setSettings(next)
      return next
    })
    setTestMsg(null)
  }

  function onProvider(id: LLMProviderId) {
    const p = PROVIDER_PRESETS[id]
    update({
      llm: {
        ...s.llm,
        provider: id,
        protocol: p.protocol,
        baseURL: p.baseURL || s.llm.baseURL,
        model: p.model || s.llm.model,
      },
    })
    setTestMsg(null)
  }

  async function ensureHostPermission(baseURL: string): Promise<void> {
    try {
      const u = new URL(baseURL)
      const origin = `${u.protocol}//${u.hostname}/*`
      const has = await chrome.permissions.contains({ origins: [origin] })
      if (!has) await chrome.permissions.request({ origins: [origin] })
    } catch {
      /* 已声明域名或无效 URL，忽略 */
    }
  }

  async function onTest() {
    setTesting(true)
    setTestMsg(null)
    await ensureHostPermission(s.llm.baseURL)
    const r = await testConnection(s.llm)
    setTestMsg({ ok: r.ok, text: r.message })
    setTesting(false)
  }

  async function onFile(file: File) {
    if (!isSupportedResume(file)) {
      setStage('error')
      setResumeMsg('仅支持 .docx / .pdf / .txt / .md')
      return
    }
    if (!s.llm.apiKey) {
      setStage('error')
      setResumeMsg('请先在上方配置 API Key —— 简历结构化需要调用 AI。')
      return
    }
    try {
      setStage('parsing')
      setResumeMsg(`正在解析 ${file.name} …`)
      const { rawText, fileName } = await parseResumeFile(file)
      if (rawText.trim().length < 50) throw new Error('解析到的文本过短，可能是扫描件/图片型简历，请换文本版。')

      setStage('building')
      setResumeMsg('AI 正在抽取简历结构化画像（约 10–20 秒）…')
      await ensureHostPermission(s.llm.baseURL)
      const profile = await buildProfile(s.llm, rawText)

      const stored: StoredResume = { fileName, rawText, profile, updatedAt: Date.now() }
      await setResume(stored)
      setResumeState(stored)
      setStage('idle')
      setResumeMsg('')
    } catch (e) {
      setStage('error')
      setResumeMsg(e instanceof Error ? e.message : String(e))
    }
  }

  async function onRebuild() {
    if (!resume?.rawText || !s.llm.apiKey) return
    try {
      setStage('building')
      setResumeMsg('AI 正在重新抽取画像…')
      const profile = await buildProfile(s.llm, resume.rawText)
      const stored: StoredResume = { ...resume, profile, updatedAt: Date.now(), profileError: undefined }
      await setResume(stored)
      setResumeState(stored)
      setStage('idle')
      setResumeMsg('')
    } catch (e) {
      setStage('error')
      setResumeMsg(e instanceof Error ? e.message : String(e))
    }
  }

  async function onDelete() {
    await clearResume()
    setResumeState(null)
    setResumeMsg('')
    setStage('idle')
  }

  if (!loaded) return null
  const preset = PROVIDER_PRESETS[s.llm.provider]
  const busy = stage === 'parsing' || stage === 'building'

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900">
      <div className="max-w-2xl mx-auto px-5 py-8 flex flex-col gap-5">
        <header className="flex items-center gap-2.5">
          <span className="text-2xl">🎯</span>
          <div>
            <h1 className="text-lg font-bold">职得投 JobOrNot · 设置</h1>
            <p className="text-[12px] text-gray-500">简历与 Key 仅存于本地浏览器；分析时浏览器直连你配置的模型，无中间服务器。</p>
          </div>
